<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Autonomous Cave Fly</title>
<style>
  body{margin:0;overflow:hidden;background:black}
  canvas{display:block;background:black}
</style>
</head>
<body>
<canvas id="game"></canvas>
<script>
const canvas=document.getElementById('game');
const ctx=canvas.getContext('2d');
const W=800, H=400;
canvas.width=W; canvas.height=H;

// Ship
const ship={x:W*0.25, y:H/2, r:8};

// Cave parameters
const maxDelta=1.5;          // center shift per frame
const minGap=120, maxGap=220; // gap size bounds
const maxGapDelta=0.5;      // gap size change per frame
const safeMargin=20;        // margin ship keeps from walls

// Generate initial cave shape
let centers=[...Array(W)].map(()=>H/2);
let gaps=[...Array(W)].map(()=> (minGap+maxGap)/2);

let distance=0;

// Main loop
function update(){
  // Shift cave left
  centers.shift(); gaps.shift();

  // Generate new column
  let lastC=centers[centers.length-1];
  let lastG=gaps[gaps.length-1];
  let newC=lastC+(Math.random()*2-1)*maxDelta;
  newC=Math.max(minGap, Math.min(H-minGap, newC));
  let newG=lastG+(Math.random()*2-1)*maxGapDelta;
  newG=Math.max(minGap, Math.min(maxGap, newG));
  centers.push(newC); gaps.push(newG);

  // Ship autopilot
  let idx=Math.floor(ship.x);
  let floorY=centers[idx]-gaps[idx]/2;
  let ceilY=centers[idx]+gaps[idx]/2;
  if(ship.y>ceilY-safeMargin) ship.y-=1;
  else if(ship.y<floorY+safeMargin) ship.y+=1;
  ship.y=Math.max(floorY+ship.r, Math.min(ceilY-ship.r, ship.y));

  // Collision?
  if(ship.y<=floorY || ship.y>=ceilY){
    return false;
  }

  distance+=2; // scroll speed
  return true;
}

function draw(){
  ctx.fillStyle='black'; ctx.fillRect(0,0,W,H);

  // Draw cave walls
  ctx.strokeStyle='white'; ctx.lineWidth=2;
  ctx.beginPath(); ctx.moveTo(0,centers[0]-gaps[0]/2);
  for(let i=1;i<W;i++) ctx.lineTo(i,centers[i]-gaps[i]/2);
  ctx.stroke();

  ctx.beginPath(); ctx.moveTo(0,centers[0]+gaps[0]/2);
  for(let i=1;i<W;i++) ctx.lineTo(i,centers[i]+gaps[i]/2);
  ctx.stroke();

  // Draw ship
  ctx.fillStyle='red';
  ctx.beginPath(); ctx.arc(ship.x,ship.y,ship.r,0,Math.PI*2);
  ctx.fill();

  // Distance counter
  ctx.fillStyle='white';
  ctx.font='20px Arial';
  ctx.fillText('Distance: '+Math.floor(distance),10,30);
}

function loop(){
  if(!update()){
    ctx.fillStyle='white';
    ctx.font='40px Arial';
    ctx.fillText('Game Over',W/2-110,H/2);
    return;
  }
  draw();
  requestAnimationFrame(loop);
}
loop();
</script>
</body>
</html>
```
The ship automatically follows the centre of the scrolling cave, steering toward the gap and incrementing a distance counter while avoiding walls.
